mapper.select:
select r.*, t.sign_time, st.name as student_name from business_student_sign_records r
left join business_teacher_sign_records t on  r.teacher_sign_id = t.id
left join business_student st on r.student_id = st.id


        AND student_id = #{studentId}


        AND teacher_sign_id = #{teacherSignId}


        AND DATE_FORMAT(t.sign_time, '%Y-%m-%d 00:00:00') = #{signTime}
